package com.example.onlinefoodorder.model;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * Order Model Class
 * Represents a customer food order in the Online Food Order System.
 * Stores order details in memory temporarily.
 */
public class Order {

    // 1. Unique Order Identifier (auto-generated by service)
    private Long orderId;

    // 2. Customer Name (cannot be blank/empty)
    @NotBlank(message = "Customer name is required")
    private String customerName;

    // 3. Food Item ordered (cannot be blank/empty)
    @NotBlank(message = "Food item cannot be empty")
    private String foodItem;

    // 4. Quantity ordered (must be at least 1)
    @NotNull(message = "Quantity is mandatory")
    @Min(value = 1, message = "Quantity must be at least 1")
    private Integer quantity;

    // 5. Price of the food order (must be positive and greater than zero)
    @NotNull(message = "Price is mandatory")
    @Positive(message = "Price must be positive and greater than zero")
    private Double price;

    /**
     * Default (no-argument) constructor
     * Required by Spring Boot and Jackson to deserialize JSON into Java objects.
     */
    public Order() {
    }

    /**
     * Parameterized constructor
     * Used to create and initialize an Order object with all fields.
     */
    public Order(Long orderId, String customerName, String foodItem, Integer quantity, Double price) {
        this.orderId = orderId;
        this.customerName = customerName;
        this.foodItem = foodItem;
        this.quantity = quantity;
        this.price = price;
    }

    // --- GETTERS AND SETTERS ---

    public Long getOrderId() {
        return orderId;
    }

    public void setOrderId(Long orderId) {
        this.orderId = orderId;
    }

    public String getCustomerName() {
        return customerName;
    }

    public void setCustomerName(String customerName) {
        this.customerName = customerName;
    }

    public String getFoodItem() {
        return foodItem;
    }

    public void setFoodItem(String foodItem) {
        this.foodItem = foodItem;
    }

    public Integer getQuantity() {
        return quantity;
    }

    public void setQuantity(Integer quantity) {
        this.quantity = quantity;
    }

    public Double getPrice() {
        return price;
    }

    public void setPrice(Double price) {
        this.price = price;
    }

    @Override
    public String toString() {
        return "Order{" +
                "orderId=" + orderId +
                ", customerName='" + customerName + '\'' +
                ", foodItem='" + foodItem + '\'' +
                ", quantity=" + quantity +
                ", price=" + price +
                '}';
    }
}
